import axios from "axios";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../Redux/Slice";
import "../style/product.css";

const API_URL =
  import.meta.env.VITE_API_URL || "http://localhost:5000";

export default function Products() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  const dispatch = useDispatch();
  const navigate = useNavigate();

  const cartItems = useSelector((state) => state.cart.items || []);

  // =========================================
  // FETCH PRODUCTS
  // =========================================

  const fetchProducts = useCallback(async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      const response = await axios.get(
        `${API_URL}/api/v1/products`,
        {
          headers: token
            ? {
                Authorization: `Bearer ${token}`,
              }
            : {},
        }
      );

      setProducts(response.data?.data || []);
    } catch (err) {
      console.error("Product fetch error:", err);

      setError(
        err.response?.data?.message ||
          "Unable to load products. Please try again."
      );
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  // =========================================
  // SEARCH
  // =========================================

  const filteredProducts = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    if (!keyword) return products;

    return products.filter((product) => {
      const name = product.name?.toLowerCase() || "";
      const description =
        product.description?.toLowerCase() || "";

      return (
        name.includes(keyword) ||
        description.includes(keyword)
      );
    });
  }, [products, search]);

  // =========================================
  // STOCK HELPERS
  // =========================================

  const getStock = (product) => {
    return Number(
      product.quantity ??
        product.stock ??
        product.inventory_quantity ??
        0
    );
  };

  const stockStats = useMemo(() => {
    return products.reduce(
      (stats, product) => {
        const stock = getStock(product);

        if (stock > 10) {
          stats.inStock += 1;
        } else if (stock > 0) {
          stats.lowStock += 1;
        } else {
          stats.outOfStock += 1;
        }

        return stats;
      },
      {
        inStock: 0,
        lowStock: 0,
        outOfStock: 0,
      }
    );
  }, [products]);

  // =========================================
  // PRODUCT CARD
  // =========================================

  const ProductCard = ({ item }) => {
    const stock = getStock(item);

    const isInCart = cartItems.some(
      (cartItem) => cartItem.id === item.id
    );

    const isOutOfStock = stock <= 0;

    let stockClass = "stock-out";
    let stockText = "Out of Stock";

    if (stock > 10) {
      stockClass = "stock-good";
      stockText = "In Stock";
    } else if (stock > 0) {
      stockClass = "stock-low";
      stockText = "Low Stock";
    }

    const price = Number(item.price || 0);

    const handleAddToCart = () => {
      if (isOutOfStock || isInCart) return;

      dispatch(addToCart(item));
    };

    return (
      <article className="product-card">
        {/* IMAGE */}
        <div className="product-image-box">
          <img
            src={
              item.image ||
              "https://via.placeholder.com/500x400?text=No+Image"
            }
            alt={item.name || "Product"}
            className="product-image"
            loading="lazy"
            onError={(event) => {
              event.currentTarget.src =
                "https://via.placeholder.com/500x400?text=No+Image";
            }}
          />

          <span className="product-id">
            #{item.id}
          </span>

          <span className={`stock-status ${stockClass}`}>
            <span className="status-dot">●</span>
            {stockText}
          </span>
        </div>

        {/* CONTENT */}
        <div className="product-content">
          <div className="product-label">
            PRODUCT
          </div>

          <h3
            className="product-name"
            title={item.name || "Unnamed Product"}
          >
            {item.name || "Unnamed Product"}
          </h3>

          <p
            className="product-description"
            title={
              item.description ||
              "No description available"
            }
          >
            {item.description ||
              "No description available for this product."}
          </p>

          {/* PRICE / STOCK */}
          <div className="product-info">
            <div className="price-section">
              <span className="info-label">
                Price
              </span>

              <strong className="product-price">
                ₹{price.toLocaleString("en-IN")}
              </strong>
            </div>

            <div className="stock-section">
              <span className="info-label">
                Available
              </span>

              <strong>
                {stock > 0
                  ? `${stock} units`
                  : "None"}
              </strong>
            </div>
          </div>

          {/* CART BUTTON */}
          <button
            type="button"
            className={`cart-button ${
              isInCart ? "cart-added" : ""
            } ${isOutOfStock ? "cart-disabled" : ""}`}
            disabled={isInCart || isOutOfStock}
            onClick={handleAddToCart}
            aria-label={
              isInCart
                ? `${item.name} is already in cart`
                : isOutOfStock
                ? `${item.name} is out of stock`
                : `Add ${item.name} to cart`
            }
          >
            <span className="cart-button-icon">
              {isInCart
                ? "✓"
                : isOutOfStock
                ? "×"
                : "🛒"}
            </span>

            {isInCart
              ? "Added to Cart"
              : isOutOfStock
              ? "Out of Stock"
              : "Add to Cart"}
          </button>
        </div>
      </article>
    );
  };

  // =========================================
  // RENDER
  // =========================================

  return (
    <main className="products-page">
      {/* HEADER */}
      <header className="products-header">
        <div className="products-heading">
          <div className="products-label">
            STORE CATALOG
          </div>

          <h1>Products</h1>

          <p>
            Manage your product catalog, pricing
            and inventory.
          </p>
        </div>

        <button
          type="button"
          className="add-product-button"
          onClick={() => navigate("/add-product")}
        >
          <span>+</span>
          Add Product
        </button>
      </header>

      {/* STATS */}
      <section className="products-stats">
        <div className="stat-card">
          <div className="stat-icon">📦</div>

          <div className="stat-text">
            <span>Total Products</span>
            <strong>{products.length}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">✓</div>

          <div className="stat-text">
            <span>In Stock</span>
            <strong>{stockStats.inStock}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">⚠</div>

          <div className="stat-text">
            <span>Low Stock</span>
            <strong>{stockStats.lowStock}</strong>
          </div>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🛒</div>

          <div className="stat-text">
            <span>Cart Items</span>
            <strong>{cartItems.length}</strong>
          </div>
        </div>
      </section>

      {/* TOOLBAR */}
      {!loading && !error && (
        <section className="products-toolbar">
          <div className="search-box">
            <span className="search-icon">
              🔍
            </span>

            <input
              type="search"
              className="search-input"
              placeholder="Search products..."
              value={search}
              onChange={(event) =>
                setSearch(event.target.value)
              }
              aria-label="Search products"
            />

            {search && (
              <button
                type="button"
                className="clear-search"
                onClick={() => setSearch("")}
                aria-label="Clear search"
              >
                ×
              </button>
            )}
          </div>

          <div className="showing-count">
            Showing{" "}
            <strong>
              {filteredProducts.length}
            </strong>{" "}
            of{" "}
            <strong>{products.length}</strong>{" "}
            products
          </div>
        </section>
      )}

      {/* LOADING */}
      {loading && (
        <section className="products-loading">
          <div className="loading-spinner"></div>

          <h3>Loading products</h3>

          <p>
            Please wait while we load your
            catalog.
          </p>
        </section>
      )}

      {/* ERROR */}
      {!loading && error && (
        <section className="products-error">
          <div className="products-error-icon">
            ⚠
          </div>

          <strong>
            Unable to load products
          </strong>

          <p>{error}</p>

          <button
            type="button"
            className="retry-button"
            onClick={fetchProducts}
          >
            Try Again
          </button>
        </section>
      )}

      {/* EMPTY */}
      {!loading &&
        !error &&
        products.length === 0 && (
          <section className="products-empty">
            <div className="empty-icon">
              📦
            </div>

            <h3>No Products Yet</h3>

            <p>
              Add your first product to start
              building your catalog.
            </p>

            <button
              type="button"
              className="add-product-button"
              onClick={() =>
                navigate("/add-product")
              }
            >
              <span>+</span>
              Add Product
            </button>
          </section>
        )}

      {/* PRODUCT GRID */}
      {!loading &&
        !error &&
        products.length > 0 && (
          <section className="products-grid">
            {filteredProducts.length > 0 ? (
              filteredProducts.map((item) => (
                <ProductCard
                  key={item.id}
                  item={item}
                />
              ))
            ) : (
              <div className="no-results">
                <div className="no-results-icon">
                  🔍
                </div>

                <h3>No Products Found</h3>

                <p>
                  No products match "
                  {search}".
                </p>

                <button
                  type="button"
                  className="clear-results-button"
                  onClick={() => setSearch("")}
                >
                  Clear Search
                </button>
              </div>
            )}
          </section>
        )}
    </main>
  );
}
